<?php
namespace App\Http\Controllers;
use App\Services\{PlatformGuests,SalonStore,Tenant,Clients,Contact,GuestBilling};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class PlatformGuestsController
{
 private function guard(Request $r):void{abort_unless($r->session()->get('platform_admin')===true,403);abort_unless(\Illuminate\Support\Facades\Schema::hasTable('security_audit_events'),503,'Előbb futtasd az adatbázis-frissítést: php artisan migrate --force');}
 private function check(Request $r,string $version):void{$v=$r->validate(['version'=>'required|string|size:64']);abort_unless(hash_equals($version,$v['version']),409,'Az adatok közben módosultak. Nyisd meg újra az adatlapot.');}
 private function contact(Request $r):array{return Contact::apply($r->validate(['name'=>'required|string|max:150','phone'=>'present|nullable|string|max:40','email'=>'present|nullable|email|max:200','notes'=>'sometimes|nullable|string|max:5000']));}
 public function index(Request $r){$this->guard($r);return response()->json(PlatformGuests::directory($r))->header('Cache-Control','no-store');}
 public function client(Request $r,int $provider,string $id){$this->guard($r);$detail=PlatformGuests::client($provider,$id);
  if($r->isMethod('GET')){if($r->has('history'))return response()->json(PlatformGuests::history($r,[['providerId'=>$provider,'clientId'=>$id]]))->header('Cache-Control','no-store');return response()->json($detail)->header('Cache-Control','no-store');}
  $values=$r->isMethod('PATCH')?$this->contact($r):$r->validate(['confirmed'=>'required|accepted']);
  app(Tenant::class)->run($provider,function()use($r,$id,$values){app(SalonStore::class)->mutate(function(&$s)use($r,$id,$values){foreach($s['clients'] as &$c)if($c['id']===$id){$this->check($r,PlatformGuests::version($c));if($r->isMethod('DELETE')){$c['deletedAt']=now()->toISOString();return;}abort_unless(Clients::visible($c),422,'Az eltávolított adatlap nem szerkeszthető.');Clients::editable($c,$values);Clients::preventDuplicate($s['clients'],array_replace($c,$values),$c);$c=array_replace($c,$values);return;}abort(404);},false);});\App\Services\SecurityAudit::platform($r,$r->isMethod('DELETE')?'guest_delete':'guest_edit',$provider,'client',$id);return response()->json(['ok'=>true]);
 }
 public function blacklist(Request $r,int $provider,string $id){$this->guard($r);$v=$r->validate(['blocked'=>'required|boolean','reason'=>'nullable|string|max:1000']);app(Tenant::class)->run($provider,function()use($r,$id,$v){app(SalonStore::class)->mutate(function(&$s)use($r,$id,$v){foreach($s['clients'] as &$c)if($c['id']===$id){$this->check($r,PlatformGuests::version($c));$c['blockedOnline']=$v['blocked'];$c['blockedReason']=$v['blocked']?($v['reason']??''):'';$c['blockedAt']=$v['blocked']?now()->toISOString():null;if($v['blocked'])$c['blockedContacts']=['email'=>$c['email']??'','phone'=>$c['phone']??''];else unset($c['blockedContacts']);return;}abort(404);},false);});\App\Services\SecurityAudit::platform($r,'guest_blacklist',$provider,'client',$id);return response()->json(['ok'=>true]);}
 public function account(Request $r,int $id){$this->guard($r);$a=PlatformGuests::account($id);$links=PlatformGuests::links($id);
  if($r->isMethod('GET')){if($r->has('history'))return response()->json(PlatformGuests::history($r,$links))->header('Cache-Control','no-store');return response()->json(['account'=>$a,'version'=>PlatformGuests::version($a),'providers'=>$links,'billing'=>GuestBilling::get($id)])->header('Cache-Control','no-store');}
  if($r->isMethod('PATCH')){$v=$this->contact($r);DB::transaction(function()use($r,$id,$v,$links){$a=(array)DB::table('guest_accounts')->select(PlatformGuests::accountFields())->where('id',$id)->lockForUpdate()->first();abort_unless($a,404);$this->check($r,PlatformGuests::version($a));foreach($links as $link)app(Tenant::class)->run($link['providerId'],function()use($link,$v){$s=app(SalonStore::class)->read();$c=collect($s['clients'])->firstWhere('id',$link['clientId']);if($c&&Clients::visible($c))Clients::preventDuplicate($s['clients'],array_replace($c,['email'=>$v['email']]),$c);});DB::table('guest_accounts')->where('id',$id)->update(['profile_name'=>$v['name'],'contact_email'=>$v['email'],'phone'=>$v['phone'],'updated_at'=>now()]);});\App\Services\SecurityAudit::platform($r,'guest_edit',null,'guest',(string)$id);return response()->json(['ok'=>true]);}
  $r->validate(['confirmed'=>'required|accepted']);DB::transaction(function()use($r,$id){$a=(array)DB::table('guest_accounts')->select(PlatformGuests::accountFields())->where('id',$id)->lockForUpdate()->first();abort_unless($a,404);$this->check($r,PlatformGuests::version($a));foreach(PlatformGuests::links($id) as $link)app(Tenant::class)->run($link['providerId'],function()use($id){app(SalonStore::class)->mutate(function(&$s)use($id){foreach($s['clients'] as &$c)if((int)($c['guestId']??0)===$id){$c['guestId']=null;unset($c['nameManaged']);}foreach($s['bookings'] as &$b)if((int)($b['guestId']??0)===$id)$b['guestId']=null;},false);});$credentials=DB::table('guest_credentials')->where('guest_id',$id)->pluck('id');DB::table('guest_auth_tokens')->whereIn('credential_id',$credentials)->delete();DB::table('guest_credentials')->where('guest_id',$id)->delete();$connections=DB::table('calendar_connections')->where('owner_type','guest')->where('owner_id',(string)$id)->pluck('id');DB::table('calendar_tasks')->whereIn('connection_id',$connections)->delete();DB::table('calendar_connections')->whereIn('id',$connections)->delete();DB::table('guest_invitations')->where('guest_id',$id)->delete();DB::table('platform_messages')->where('recipient_type','guest')->where('recipient_id',$id)->delete();DB::table('guest_accounts')->where('id',$id)->delete();});\App\Services\SecurityAudit::platform($r,'guest_delete',null,'guest',(string)$id);return response()->json(['ok'=>true]);
 }
}
